@namespace sv_8712015b16a74ef3b520637b95375638.Components.Pages.Settings
@using sv_8712015b16a74ef3b520637b95375638.Services
@using sv_8712015b16a74ef3b520637b95375638.Models
@inject ISettingsService SettingsService

<div class="appearance-section">
    @if (_loading)
    {
        <div class="text-center py-5">
            <div class="spinner-border text-primary" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else
    {
        <h4 class="section-heading">Appearance</h4>
        <p class="text-muted mb-4">Customize how the application looks and feels.</p>

        @if (!string.IsNullOrEmpty(_statusMessage))
        {
            <div class="alert alert-success alert-dismissible fade show" role="alert">
                @_statusMessage
                <button type="button" class="btn-close" @onclick="() => _statusMessage = null"></button>
            </div>
        }

        <div class="row">
            <div class="col-md-7">
                <!-- Theme -->
                <div class="card mb-4">
                    <div class="card-body">
                        <h6 class="fw-semibold mb-3">Theme</h6>
                        @foreach (var theme in _themes)
                        {
                            <div class="form-check mb-2">
                                <input class="form-check-input" type="radio" name="theme"
                                       id="@($"theme-{theme}")"
                                       value="@theme"
                                       checked="@(_theme == theme)"
                                       @onchange="() => _theme = theme" />
                                <label class="form-check-label" for="@($"theme-{theme}")">
                                    @GetThemeIcon(theme) @theme
                                </label>
                            </div>
                        }
                    </div>
                </div>

                <!-- Font Size -->
                <div class="card mb-4">
                    <div class="card-body">
                        <h6 class="fw-semibold mb-3">Font Size</h6>
                        <div class="btn-group w-100" role="group">
                            @foreach (var size in _fontSizes)
                            {
                                <button type="button"
                                        class="btn @(_fontSize == size ? "btn-primary" : "btn-outline-primary")"
                                        @onclick="() => _fontSize = size">
                                    @size
                                </button>
                            }
                        </div>
                    </div>
                </div>

                <!-- Language -->
                <div class="card mb-4">
                    <div class="card-body">
                        <h6 class="fw-semibold mb-3">Language</h6>
                        <select class="form-select" @bind="_language">
                            @foreach (var lang in _languages)
                            {
                                <option value="@lang">@lang</option>
                            }
                        </select>
                    </div>
                </div>

                <!-- Compact Mode -->
                <div class="card mb-4">
                    <div class="card-body">
                        <div class="form-check form-switch">
                            <input class="form-check-input" type="checkbox" id="compactMode"
                                   checked="@_compactMode"
                                   @onchange="e => _compactMode = (bool)(e.Value ?? false)" />
                            <label class="form-check-label" for="compactMode">
                                <strong>Compact Mode</strong>
                                <br /><small class="text-muted">Reduce spacing and padding for a denser layout</small>
                            </label>
                        </div>
                    </div>
                </div>
            </div>

            <!-- Live Preview -->
            <div class="col-md-5">
                <div class="card sticky-top" style="top: 1rem;">
                    <div class="card-header fw-semibold">
                        👁️ Live Preview
                    </div>
                    <div class="card-body preview-area @GetPreviewClasses()">
                        <div class="preview-header mb-2">Dashboard</div>
                        <p class="preview-text">
                            This is a preview of how your content will look with the selected appearance settings.
                        </p>
                        <div class="d-flex gap-2 mb-2">
                            <span class="badge bg-primary">Tag</span>
                            <span class="badge bg-secondary">Label</span>
                        </div>
                        <div class="preview-card">
                            <strong>Sample Card</strong>
                            <p class="mb-0 mt-1">Card content with @_fontSize.ToLower() font size.</p>
                        </div>
                        <button class="btn btn-sm btn-primary mt-2">Sample Button</button>
                    </div>
                </div>
            </div>
        </div>

        <button class="btn btn-primary mt-2" @onclick="SaveAsync" disabled="@_saving">
            @if (_saving)
            {
                <span class="spinner-border spinner-border-sm me-1" role="status"></span>
            }
            Save
        </button>
    }
</div>

@code {
    private bool _loading = true;
    private bool _saving;
    private string? _statusMessage;

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    private static readonly string[] _themes = ["Light", "Dark", "System"];
    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private static readonly string[] _languages =
        ["English", "Spanish", "French", "German", "Japanese", "Chinese", "Korean", "Portuguese"];

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _statusMessage = null;
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _statusMessage = "Appearance settings saved!";
        _saving = false;
    }

    private string GetPreviewClasses()
    {
        var classes = new List<string>();

        classes.Add(_theme switch
        {
            "Dark" => "preview-dark",
            _ => "preview-light"
        });

        classes.Add(_fontSize switch
        {
            "Small" => "preview-font-sm",
            "Large" => "preview-font-lg",
            _ => "preview-font-md"
        });

        if (_compactMode) classes.Add("preview-compact");

        return string.Join(" ", classes);
    }

    private static string GetThemeIcon(string theme) => theme switch
    {
        "Light" => "☀️",
        "Dark" => "🌙",
        "System" => "💻",
        _ => ""
    };
}

.appearance-section .section-heading {
    font-weight: 600;
    margin-bottom: 0.25rem;
}

/* Live Preview Styles */
.preview-area {
    transition: all 0.2s ease;
    border-radius: 0.25rem;
    min-height: 220px;
}

.preview-header {
    font-weight: 700;
    font-size: 1.1em;
}

.preview-card {
    border: 1px solid rgba(0,0,0,0.1);
    border-radius: 0.375rem;
    padding: 0.75rem;
}

/* Theme variants */
.preview-light {
    background-color: #ffffff;
    color: #212529;
}

.preview-light .preview-card {
    background-color: #f8f9fa;
    border-color: #dee2e6;
}

.preview-dark {
    background-color: #1e1e2e;
    color: #cdd6f4;
}

.preview-dark .preview-card {
    background-color: #313244;
    border-color: #45475a;
    color: #cdd6f4;
}

.preview-dark .badge.bg-secondary {
    background-color: #45475a !important;
}

/* Font size variants */
.preview-font-sm {
    font-size: 0.8rem;
}

.preview-font-md {
    font-size: 0.95rem;
}

.preview-font-lg {
    font-size: 1.15rem;
}

/* Compact mode */
.preview-compact {
    padding: 0.5rem !important;
    line-height: 1.3;
}

.preview-compact .preview-card {
    padding: 0.4rem;
}

.preview-compact .preview-text {
    margin-bottom: 0.25rem;
}

.preview-compact .mb-2 {
    margin-bottom: 0.25rem !important;
}

